import re,math
from metrics import parse

def value(samples,name,labels=None):
    indexed={}
    for metric,tags,number in samples:
        key=(metric,frozenset(tags.items()))
        indexed.setdefault(key,[]).append(number)
    selected=[number for (metric,tags),numbers in indexed.items()if metric==name and(labels is None or tags==frozenset(labels.items()))for number in numbers]
    if len(selected)>1:raise ValueError('ambiguous native selector')
    return selected[0]if selected else None


def audit_migration(collect,policy):
    if not callable(collect)or type(policy)is not dict or set(policy)!={'asset_id','role','old_device','new_device'}:raise ValueError('approved mapping required')
    for key,item in policy.items():
        if type(item)is not str or not re.fullmatch(r'[A-Za-z0-9_.:-]{1,64}',item):raise ValueError('bounded nonempty mapping identifiers required')
    old,new=policy['old_device'],policy['new_device']
    if old==new:raise ValueError('different device names required')
    rows=[]
    for device in (old,new,new):
        observation=collect()
        if type(observation)is not dict or set(observation)!={'status','body','observed_at_ns'}or type(observation['status'])is not int or observation['status']!=200 or type(observation['body'])is not str or len(observation['body'].encode())>1048576 or type(observation['observed_at_ns'])is not int or observation['observed_at_ns']<0:raise ValueError('valid bounded native observation required')
        samples=parse(observation['body'])
        if value(samples,'node_scrape_collector_success',{'collector':'netdev'})!=1:raise ValueError('netdev collection unavailable')
        counters={}
        for direction in ('receive','transmit'):
            item=value(samples,'node_network_'+direction+'_bytes_total',{'device':device})
            if item is None or not math.isfinite(item)or item<0 or not item.is_integer()or item>2**53:raise ValueError('exact nonnegative byte counter required')
            counters[direction]=int(item)
        if rows and observation['observed_at_ns']<=rows[-1]['observed_at_ns']:raise ValueError('strictly increasing observation times required')
        rows.append(dict(device=device,observed_at_ns=observation['observed_at_ns'],**counters))
    interval={}
    for direction in ('receive','transmit'):
        before,after=rows[1][direction],rows[2][direction]
        interval[direction]=dict(reset=after<before,delta_bytes=None if after<before else after-before)
    return dict(schema=1,asset_id=policy['asset_id'],role=policy['role'],observations=rows,historical_continuity=False,rename_delta_bytes=None,new_device_interval=interval)
